<body>
<main class="wrap">
<h1>Trip Cost Splitter</h1>
<p class="hint">Log each expense, then see who owes whom. Everyone shares costs equally.</p>

<section class="card" aria-labelledby="add-h">
<h2 id="add-h">Add an expense</h2>
<form id="add-form" novalidate>
<label for="desc">What was it for?</label>
<input id="desc" type="text" autocomplete="off" placeholder="e.g. Dinner on Saturday">
<div class="row">
<div>
<label for="amount">Amount</label>
<input id="amount" type="number" inputmode="decimal" min="0" step="0.01" placeholder="0.00">
</div>
<div>
<label for="payer">Paid by</label>
<select id="payer"></select>
</div>
</div>
<button type="submit" class="btn-primary">Add expense</button>
</form>
</section>

<section class="card" aria-labelledby="list-h">
<h2 id="list-h">Expenses</h2>
<ul id="exp-list"></ul>
</section>

<section class="card" aria-labelledby="res-h">
<h2 id="res-h">Who owes whom</h2>
<div id="results"></div>
<div class="btn-row">
<button id="clear-btn" class="btn-danger" type="button">Clear all</button>
</div>
</section>

<p class="sr" id="status" aria-live="polite"></p>
</main>

<script>
(function(){
var PEOPLE=['Levente','Anna','Peti'];
var KEY='trip-splitter-v1';
var store={data:null};
var expenses=[];
var confirmTimer=null;
var clearTimer=null;

function money(n){return (Math.round(n*100)/100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});}
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}

function compute(){
var n=PEOPLE.length;
var paid=PEOPLE.map(function(){return 0;});
var total=0;
expenses.forEach(function(e){var i=PEOPLE.indexOf(e.payer);if(i>=0){paid[i]+=e.amount;total+=e.amount;}});
var share=n?total/n:0;
var net=paid.map(function(p){return p-share;});
var pos=[],neg=[];
for(var i=0;i<n;i++){if(net[i]>0.005)pos.push({i:i,v:net[i]});else if(net[i]<-0.005)neg.push({i:i,v:-net[i]});}
pos.sort(function(a,b){return b.v-a.v;});neg.sort(function(a,b){return b.v-a.v;});
var transfers=[];var pi=0,ni=0;
while(pi<pos.length&&ni<neg.length){
var amt=Math.min(pos[pi].v,neg[ni].v);
transfers.push({from:neg[ni].i,to:pos[pi].i,amt:amt});
pos[pi].v-=amt;neg[ni].v-=amt;
if(pos[pi].v<0.005)pi++;
if(neg[ni].v<0.005)ni++;
}
return {total:total,share:share,net:net,transfers:transfers};
}

function arm(btn,onDone){
if(btn.classList.contains('confirming')){clearTimeout(confirmTimer);btn.classList.remove('confirming');btn.textContent=btn.dataset.label;onDone();}
else{btn.dataset.label=btn.textContent;btn.classList.add('confirming');btn.textContent='Tap again to confirm';clearTimeout(confirmTimer);confirmTimer=setTimeout(function(){btn.classList.remove('confirming');btn.textContent=btn.dataset.label;},3000);}
}

function render(){
var list=document.getElementById('exp-list');
if(!expenses.length){list.innerHTML='<li class="empty">No expenses yet — add your first one above.</li>';}
else{list.innerHTML=expenses.map(function(e,idx){
return '<li class="exp"><div class="exp-main"><div class="exp-desc">'+esc(e.desc)+'</div><div class="exp-meta">Paid by '+esc(e.payer)+' · shared equally</div></div><div class="exp-amt">'+money(e.amount)+'</div><button class="exp-del" type="button" data-idx="'+idx+'" aria-label="Delete '+esc(e.desc)+'">✕</button></li>';
}).join('');}

var c=compute();
var res=document.getElementById('results');
var h='<div>';
PEOPLE.forEach(function(name,i){
var v=c.net[i];var cls=v>0.005?'pos':(v<-0.005?'neg':'zero');
var label=v>0.005?'+'+(v>0?'':'')+money(v):(v<-0.005?'−'+money(-v):money(0));
h+='<div class="balance"><span class="b-name">'+esc(name)+'</span><span class="b-amt '+cls+'">'+label+'</span></div>';
});
h+='</div>';
h+='<div style="margin-top:14px">';
if(!expenses.length){h+='<p class="empty">Add some expenses to see the split.</p>';}
else if(!c.transfers.length){h+='<p class="empty">All settled up — nobody owes anyone.</p>';}
else{h+=c.transfers.map(function(t){return '<div class="settle"><b>'+esc(PEOPLE[t.from])+'</b> pays <b>'+esc(PEOPLE[t.to])+'</b> '+money(t.amt)+'</div>';}).join('');}
h+='<div class="total">Total spent: '+money(c.total)+' · '+money(c.share)+' per person</div>';
h+='</div>';
res.innerHTML=h;
}

function save(){if(window.alfy&&window.alfy.storage){try{window.alfy.storage.set(KEY,expenses);}catch(e){}}}
function say(msg){document.getElementById('status').textContent=msg;}

function init(){
var sel=document.getElementById('payer');
sel.innerHTML=PEOPLE.map(function(p){return '<option>'+esc(p)+'</option>';}).join('');
if(window.alfy&&window.alfy.storage){Promise.resolve(window.alfy.storage.get(KEY)).then(function(v){if(Array.isArray(v))expenses=v;render();}).catch(function(){});}
render();
}

document.getElementById('add-form').addEventListener('submit',function(ev){
ev.preventDefault();
var desc=document.getElementById('desc');
var amt=document.getElementById('amount');
var d=desc.value.trim();
var a=parseFloat(amt.value);
if(!d){say('Please describe the expense.');desc.focus();return;}
if(!(a>0)){say('Please enter an amount greater than 0.');amt.focus();return;}
expenses.push({desc:d,amount:a,payer:document.getElementById('payer').value});
save();render();
desc.value='';amt.value='';desc.focus();
say('Added: '+d);
});

document.getElementById('exp-list').addEventListener('click',function(ev){
var b=ev.target.closest('.exp-del');if(!b)return;
arm(b,function(){var i=parseInt(b.dataset.idx,10);var removed=expenses.splice(i,1)[0];save();render();say('Removed: '+(removed?removed.desc:''));});
});

var clearBtn=document.getElementById('clear-btn');
clearBtn.addEventListener('click',function(){
arm(clearBtn,function(){
if(!expenses.length){say('Nothing to clear.');return;}
expenses=[];save();render();say('Cleared all expenses.');
});
});

init();
})();
</script>
</body>
</html>
